import{_ as t,o,c as n,a3 as a}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"换成自己的 key","description":"","frontmatter":{},"headers":[],"relativePath":"zh/own-key.md","filePath":"zh/own-key.md"}'),r={name:"zh/own-key.md"};function d(l,e,i,s,c,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="换成自己的-key" tabindex="-1">换成自己的 key <a class="header-anchor" href="#换成自己的-key" aria-label="Permalink to &quot;换成自己的 key&quot;">​</a></h1><p>nanoMuse 免费、非营利。它背后的模型要花钱，每个账号的起始额度由开发者出（应用里显示的是中继当前的数字）。额度用完以后，有两条路可以继续走，都不需要 nanoMuse 再提供什么：在某家模型服务商申请一把自己的 key，或者用你已经在付费的套餐（ChatGPT、Claude、Kimi）在应用里登录。</p><p>每个客户端读的都是同一份服务商清单，每家能做什么也写在里面：<strong>对话</strong>、<strong>动手</strong>（一个能看截图的模型）、<strong>画图</strong>（形象工作室）和<strong>视频</strong>（形象的短视频）。没有任何已配置的服务商能做的功能，就干脆不提供，只用一句话说明哪些服务商可以；什么都不会坏。</p><p>你的登录、邀请码和设备都不受影响：账号还是那个账号，换的只是模型服务商。用上自己的 key 或套餐之后，你说的话不再经过 nanoMuse Cloud。</p><h2 id="where-you-are-decides-who-comes-first" tabindex="-1">先看你在哪 <a class="header-anchor" href="#where-you-are-decides-who-comes-first" aria-label="Permalink to &quot;先看你在哪 {#where-you-are-decides-who-comes-first}&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>首选</th><th>一把 key 能做什么</th></tr></thead><tbody><tr><td>中国大陆</td><td><strong>阿里云百炼</strong></td><td>对话、动手、画图、生成视频，四样都在一把 key 下</td></tr><tr><td>海外</td><td><strong>OpenRouter</strong>，其次 <strong>OpenAI</strong></td><td>对话、动手、画图；生成视频目前只有百炼</td></tr></tbody></table><p>百炼只给中国大陆身份注册；海外用户一个 OpenRouter 账号就能用到几百个模型，按量付费。首选之外，下面的每一家都可以单独用，或者和另一家搭配，比如对话用 DeepSeek、画图用智谱。</p><p>四件事、四个设置、一个页面：Android、iPhone 和桌面版都是 <strong>设置 › 模型</strong>，网页控制台是「连接」页。四行分别是「对话」「操作屏幕」「生成图片」「生成视频」；每行显示 <code>服务商 · 模型</code>，点开是一个只列能做这件事的模型的选择器（操作屏幕需要能看图的模型）。iPhone 上「操作屏幕」这一行是灰的（「不在 iPhone 上」）：手机不能操作自己的屏幕，电脑用它自己的设置。细节见下面的<a href="#which-model-does-what">哪个模型做哪件事</a>。</p><h2 id="what-each-provider-covers" tabindex="-1">各家服务商能做什么 <a class="header-anchor" href="#what-each-provider-covers" aria-label="Permalink to &quot;各家服务商能做什么 {#what-each-provider-covers}&quot;">​</a></h2><p>对话 = 聊天；动手 = 看截图操作手机和电脑；画图 = 形象工作室的图片；视频 = 形象的短动画。</p><table tabindex="0"><thead><tr><th>服务商</th><th style="text-align:center;">对话</th><th style="text-align:center;">动手</th><th style="text-align:center;">画图</th><th style="text-align:center;">视频</th><th>地区</th><th>申请 key</th></tr></thead><tbody><tr><td>阿里云百炼</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td>中国大陆</td><td><a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a></td></tr><tr><td>DeepSeek</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以</td><td><a href="https://platform.deepseek.com/api_keys" target="_blank" rel="noreferrer">platform.deepseek.com</a></td></tr><tr><td>Kimi（月之暗面）</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以（国内 / 国际两个版本）</td><td><a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a> · <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a></td></tr><tr><td>智谱 GLM</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>中国大陆</td><td><a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a></td></tr><tr><td>硅基流动</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>中国大陆</td><td><a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a></td></tr><tr><td>火山方舟（豆包）</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>中国大陆</td><td><a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a></td></tr><tr><td>MiniMax</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以（国内 / 国际两个版本）</td><td><a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a></td></tr><tr><td>OpenRouter</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>OpenAI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a></td></tr><tr><td>Anthropic Claude</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a></td></tr><tr><td>Google Gemini</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com</a></td></tr><tr><td>xAI Grok</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr><tr><td>Groq</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com</a></td></tr><tr><td>Mistral AI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai</a></td></tr><tr><td>OpenCode Zen</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>OpenCode Go</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>Ollama / LM Studio / vLLM（本机）</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以</td><td>不需要 key</td></tr></tbody></table><p>「视频」一栏只有百炼，是因为 nanoMuse 的视频生成走的是百炼的接口；其他家的视频模型用的是各自的任务接口，这一轮还没有接。「画图」一栏里，OpenRouter 走的是它的 Image API，模型例如 <code>openai/gpt-image-2</code>；Gemini 用 <code>gemini-2.5-flash-image</code>。</p><p>这张表来自仓库里的目录文件 <a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/llm/providers.json" target="_blank" rel="noreferrer"><code>nanomuse/llm/providers.json</code></a>：每个客户端、中继都读它，地址、默认模型和「能做什么」都在里面；表里的事实在 2026 年 10 月对照各家文档核过。</p><h2 id="making-a-key" tabindex="-1">怎么申请 key <a class="header-anchor" href="#making-a-key" aria-label="Permalink to &quot;怎么申请 key {#making-a-key}&quot;">​</a></h2><p>每家的步骤都是一样的三步：注册 → 控制台里创建 API key → 复制到 nanoMuse。<strong>key 只给 nanoMuse 用，不要发给任何人、不要贴到聊天里。</strong></p><ul><li><strong>阿里云百炼。</strong> 用阿里云账号登录 <a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a>（要实名认证），首次进入点「开通百炼服务」，再到 <a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">API-KEY 页</a> 创建；key 以 <code>sk-</code> 开头。新账号有一段时间的免费 token。建议在控制台设一个用量告警。</li><li><strong>DeepSeek。</strong> <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a> 注册、充值、API Keys 里创建。地址 <code>https://api.deepseek.com/v1</code>。</li><li><strong>Kimi。</strong> 国内版在 <a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a>，地址 <code>https://api.moonshot.cn/v1</code>；国际版在 <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a>，地址 <code>https://api.moonshot.ai/v1</code>。两个版本的账号和 key 不通用。</li><li><strong>智谱 GLM。</strong> <a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a>，地址 <code>https://open.bigmodel.cn/api/paas/v4</code>。</li><li><strong>硅基流动。</strong> <a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a>，地址 <code>https://api.siliconflow.cn/v1</code>；模型 id 带厂商前缀，例如 <code>deepseek-ai/DeepSeek-V4-Flash</code>。</li><li><strong>火山方舟。</strong> <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a>，先在方舟里开通要用的模型，再创建 key；地址 <code>https://ark.cn-beijing.volces.com/api/v3</code>。</li><li><strong>MiniMax。</strong> 国内版 <a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a>，地址 <code>https://api.minimaxi.com/v1</code>；国际版地址 <code>https://api.minimax.io/v1</code>。</li><li><strong>OpenRouter。</strong> <a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a> 用 Google、GitHub 或邮箱登录，<em>Credits</em> 里充值，<em>Keys</em> 里创建；key 以 <code>sk-or-v1-</code> 开头。<em>Settings → Limits</em> 可以给 key 设每月上限。</li><li><strong>OpenAI。</strong> <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a>，地址 <code>https://api.openai.com/v1</code>。</li><li><strong>Anthropic。</strong> <a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a>。nanoMuse 直接用 Anthropic 的接口，不需要兼容层。</li><li><strong>Google Gemini。</strong> <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com/apikey</a>，地址 <code>https://generativelanguage.googleapis.com/v1beta/openai</code>。</li><li><strong>xAI、Groq、Mistral。</strong> 各自的控制台创建 key；地址分别是 <code>https://api.x.ai/v1</code>、<code>https://api.groq.com/openai/v1</code>、<code>https://api.mistral.ai/v1</code>。</li><li><strong>OpenCode Zen。</strong> 在 <a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> 申请 key；按请求从余额里扣费，有几个模型免费。地址 <code>https://opencode.ai/zen/v1</code>。只有 OpenAI 格式的那些模型到得了，所以只有对话、没有动手：OpenCode 列出的视觉模型 <code>deepseek-v4-flash-vision-exp</code> 在 DeepSeek 自家平台上已经退役。OpenCode 没有套餐登录，只有 key，所以这里没有可以登录的东西。</li><li><strong>OpenCode Go。</strong> 同一域名上的订阅：在 OpenCode 控制台订阅 Go（每月 10 美元）或 Go Plus（每月 40 美元），再到 <a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> 申请 key。地址 <code>https://opencode.ai/zen/go/v1</code>。用量按模型计，分每月、每周和每 5 小时三档上限。OpenCode 把 Go 定位给编程智能体，要求客户端说明自己是谁，并在 <code>x-opencode-session</code> 里为每个对话带上一个固定的 id（<a href="https://opencode.ai/go" target="_blank" rel="noreferrer">它的 Go 页面</a>，「Can I use Go with other coding agents?」一条）。运行时（也就是网页控制台）每次请求 Go 都把 <code>nanoMuse/&lt;版本&gt;</code> 作为 user agent，并在这个请求头里带上对话的 id；不属于任何对话的调用（比如连接测试）带的是它自己的 id。桌面版把 Go 写成模型适配器自带的 OpenCode Go 路由，这条路由同样会带上这个请求头，并按每个模型自己的格式访问：桌面版提供这条路由的目录里列出的模型，走 Responses 和 Messages 格式的也在内；其他地方只走 OpenAI 格式。手机端也会发：对 OpenCode 域名的对话和 Responses 请求都带上这个请求头，id 是这个聊天的提示缓存键，由第一条消息算出，每一轮都一样（开头一字不差的两个聊天会共用一个）。和 Zen 一样只有对话。</li></ul><p><strong>贴到 nanoMuse 里。</strong></p><ul><li>手机：额度用完时卡片上的「去设置」会打开预填好的服务商表单；或者 设置 → 服务商 → 添加，选服务商，贴 key，保存。</li><li>桌面版：额度卡片上的「去设置」会打开 设置 → nanoMuse Cloud 并停在那家服务商的一行；或者直接在那里「可用的途径」下面那家服务商的一行里贴 key。地址已经填好。</li><li>网页控制台：额度卡片上的「去设置」会打开「连接」页并选好服务商；或者 连接 → 对话模型，点服务商，贴 key，保存。</li><li>自己跑的运行时：在 <code>config.toml</code> 里写 <code>[llm] provider = &quot;bailian&quot;</code>（表里任一服务商的 id）加 <code>api_key</code>，地址和默认模型会从目录文件里补上；画图、生成视频用另一家，就加 <code>[image]</code> / <code>[video]</code> 一段（<a href="./configuration#image-and-video">configuration.md</a>）。</li></ul><p><strong>用它来做什么。</strong> key 保存好之后，会弹出一张卡片问这把 key 负责哪些事：这家服务商能做的每件事一个开关（对话、操作屏幕、生成图片、生成视频），默认全开。「就这样」把勾上的几行切到这家服务商，每件事用目录里的默认模型（目录里的默认模型不在它的列表里时，用列表里第一个能做这件事的）；「暂不」什么都不改，关掉的开关也什么都不改。登录了 nanoMuse Cloud 的话，卡片会说其余仍由 nanoMuse Cloud 负责。每一行以后都可以在 设置 › 模型 里改（网页控制台：「连接」页）。</p><h2 id="which-model-does-what" tabindex="-1">哪个模型做哪件事 <a class="header-anchor" href="#which-model-does-what" aria-label="Permalink to &quot;哪个模型做哪件事 {#which-model-does-what}&quot;">​</a></h2><p>设置 › 模型（Android：设置顶部的那张卡；iPhone：设置的第一张卡；桌面版：紧跟「通用」；网页控制台：「连接」页上的「对话模型」「手的模型」「生成图片」「生成视频」几张卡）一件事一行：</p><table tabindex="0"><thead><tr><th>行</th><th>做什么</th><th>列出谁</th></tr></thead><tbody><tr><td>对话</td><td>和你说话的模型。</td><td>登录且开着 nanoMuse Cloud 模型时先是它的对话模型，然后是你每一家有对话模型的服务商</td></tr><tr><td>操作屏幕</td><td>看着屏幕替你操作，需要能看图的模型。</td><td>nanoMuse Cloud 的手的模型，然后是你的服务商里能看图的模型；iPhone 上是灰的（「不在 iPhone 上」）</td></tr><tr><td>生成图片</td><td>形象的肖像，以及你要的图片。</td><td>nanoMuse Cloud，然后是你有图像模型的服务商</td></tr><tr><td>生成视频</td><td>形象的短视频。</td><td>nanoMuse Cloud，然后是你有视频模型的服务商（百炼）</td></tr></tbody></table><p>每行显示 <code>服务商 · 模型</code>，点开是选择器：登录时 nanoMuse Cloud 一组在最前，推荐的那个有标记，然后你的每家服务商一组，只列能做这件事的模型。没有这项能力的服务商在这一行里根本不出现。一行里什么都没有时，显示那句「谁能提供」的话和「添加服务商」。对话这一行选了，就是新对话的默认，主要聊天也跟着走（「对主要聊天和新对话生效；旁聊保留自己的模型。」）：主要聊天是聊天标签页始终显示的那一个对话，永远不算「新对话」，不这样的话就会一直停在它开始时的服务商上；已经打开的旁聊保留它的模型。还没写过字的对话也跟着走：刚登录后的主要聊天（账号一开始是一个空对话），或者你新开了又放着的对话。所以「对话」这一行写的是什么，你发出的下一条消息就由谁来回答，主要聊天和新对话都是，不管之前用的是哪个来源：你登录的套餐（ChatGPT、Claude、Kimi）、你自己的 key，还是 nanoMuse Cloud；登录永远不会抢在你的选择前面。手机和桌面版都是这样。在对话自己的选择器里（<code>•••</code> 菜单的一行，或它下面的一个模型）选了你自己的模型组，这个组就原样成为默认，不会被重新排序，主要聊天带着对话解析出的那个模型跟过去；只有以服务商命名、且只含这一家服务商的组，才会像在模型页里选择那样把选中的模型排到最前。手机上你的模型组可以带一个默认思考等级（iPhone 的「全部设置 › 模型组」，Android 从对话选择器进入的「模型组」），主要聊天跟着选择走的时候，这个等级一起带过去，和新对话、对话自己的选择器一样。</p><p><strong>自动。</strong> 操作屏幕、生成图片、生成视频三行打开时第一项是「自动」，写着它现在给的是什么（比如「当前为 nanoMuse Cloud · qwen3.8-27b」）。选它，这一行忘掉在这里做过的选择，按一个顺序走：对话模型所在的服务商是你自己的、而且能做这件事时用它（目录里的默认模型）；否则登录且开着 nanoMuse Cloud 模型时用它；否则用你第一家能做这件事的服务商。你做过的选择永远优先；nanoMuse Cloud 不会排到你选的服务商前面。每台设备各自选，因为 key 不会离开录入它的那台设备。</p><p><strong>不会悄悄回退。</strong> 你自己的模型在某一轮失败时，什么都不会自动切换：错误卡片上多一个按钮「这次改用 nanoMuse Cloud」（只在登录时出现），只把这一轮放到账号的模型上重跑，不改任何一行。桌面版在形象工作室的一轮失败和一组短视频失败之后也给同一个按钮。</p><p><strong>思考深度（桌面版）。</strong> 输入框的模型选择器会给你自己的模型提供思考深度，前提是服务商的文档写明了怎么控制，发送时用的也是服务商自己的字段：DeepSeek、Kimi（kimi-k3）、智谱（GLM-5.2 和 5.3）、硅基流动和火山引擎（它们的 DeepSeek-V4、GLM-5.2 以及豆包 Seed 2）、MiniMax（M3.1）、OpenRouter（按它模型列表里每个模型给出的档位）、OpenAI（o 系列、GPT-5 起）、Anthropic（Claude 4.6 起）、走 OpenAI 兼容层的 Gemini、xAI（Grok 4.5 起）、Groq、Mistral，以及 Ollama 或 vLLM 上的 gpt-oss。档位就是服务商自己的（比如 DeepSeek 是 <code>low</code>、<code>high</code>、<code>max</code>），「服务商默认」什么都不发，模型按服务商文档里的默认方式思考。没有「关闭」这一项：在这些服务商那里，关掉思考是另一个开关或另一个模型。没有文档写明档位的模型不显示这个控件，百炼（它的开关是 <code>enable_thinking</code>，没法不发）、LM Studio 和自定义端点也不显示。在这个版本之前保存的 key，下次启动时会拿到这个控件。</p><p><strong>关掉 nanoMuse Cloud。</strong> 登录时，模型页上有一个开关「使用 nanoMuse Cloud 模型」。关掉之后，nanoMuse Cloud 从选择器和自动顺序里退出，任何附带的调用（对话标题、记忆、形象、动手）都不会在它上面运行，唯一会消耗额度的是「这次改用 nanoMuse Cloud」这个按钮，而且只在你每次点它的时候。账号保持登录：同步、你的设备和账号页照常工作。nanoMuse Cloud 这家服务商不能像你自己添加的那样删除（删除它就等于退出登录）；退出登录在「设置 › nanoMuse Cloud」里。</p><p><strong>不用账号。</strong> 有自己的 key，应用在未登录时一样能用：对话、动手、生成图片和短视频都跑在你的服务商上，第一屏在登录旁边给了「改用自己的 API key」。只有 nanoMuse Cloud 的模型、对话同步和设备互通才需要登录。</p><p><strong>已知的限制。</strong> iPhone 上生成图片、生成视频两行除了 nanoMuse Cloud，只列你在 DashScope 主机上的服务商（阿里云百炼）；目录里说能画图的 key（OpenRouter、OpenAI、Gemini、自定义接口）会在选择页下方用一句「此处不提供：……」点名，并说明它在哪里能用，免得你以为手机把它弄丢了。桌面版的手只说 OpenAI 的接口形状，所以 Anthropic 和原生 Gemini 的 key 在操作屏幕那一行下面用一句话点出来、不列进去；手的改动在手的下一步生效，不用重启。用 Gemini 的 key 画图走的是 Google 的 OpenAI 兼容层：<code>images/generations</code> 接受 <code>gemini-2.5-flash-image</code>，但 Google 的页面没有写明那里有 <code>images/edits</code>，所以形象工作室里的姿势图用 Gemini 的 key 可能画不出来。</p><h2 id="sign-in-with-a-plan-you-already-pay-for" tabindex="-1">用你已经在付费的套餐登录 <a class="header-anchor" href="#sign-in-with-a-plan-you-already-pay-for" aria-label="Permalink to &quot;用你已经在付费的套餐登录 {#sign-in-with-a-plan-you-already-pay-for}&quot;">​</a></h2><p>有些套餐可以直接登录使用，不用申请 key：</p><table tabindex="0"><thead><tr><th>套餐</th><th>能做什么</th><th>哪里可以登录</th></tr></thead><tbody><tr><td><strong>ChatGPT</strong>（Plus / Pro / Team）</td><td>对话、动手</td><td>Android、iPhone、桌面版、网页版</td></tr><tr><td><strong>Claude</strong>（Pro / Max）</td><td>对话、动手</td><td>Android、iPhone</td></tr><tr><td><strong>Kimi</strong></td><td>对话、动手</td><td>Android、iPhone（设备码登录）</td></tr><tr><td><strong>OpenRouter</strong></td><td>对话、动手、画图</td><td>Android、iPhone（一键登录，key 自动回到 App）</td></tr></tbody></table><p>ChatGPT 登录走的是 OpenAI 自家 Codex 的授权流程（网页控制台：连接 → 「或者用 ChatGPT 套餐登录」；桌面版：设置 → nanoMuse Cloud 里的 ChatGPT 一行；手机：设置 → 服务商 → OpenAI → 登录）。登录后只有对话和动手：Codex 这条通道没有图像和视频接口，画图和生成视频仍要配一把 key。</p><p>在终端里也可以：<code>nanomuse chatgpt login</code> 打开登录页并等浏览器回来，<code>nanomuse chatgpt status</code> 看登录的是谁、什么时候过期，<code>nanomuse chatgpt logout</code> 忘掉它；然后在 <code>config.toml</code> 里写 <code>[llm] provider = &quot;chatgpt&quot;</code>（不用 <code>base_url</code>、<code>api_key</code>，<code>model</code> 留空就是 <code>gpt-5.6-sol</code>）。浏览器要能访问运行时所在机器的 1455 端口；运行时在别的机器上时，把浏览器最后停在的那个地址整条复制下来，贴给命令行的提示，或者 <code>POST /api/chatgpt/callback {&quot;url&quot;: …}</code>（<a href="./configuration#a-chatgpt-plan-instead-of-a-key">configuration.md</a>）。</p><p><strong>手机上的代理或 VPN 可能吞掉回调。</strong> Android 上，登录页会把浏览器送回 <code>http://localhost:1455/auth/callback</code>，这个地址只有同一部手机上的 App 会应答。把所有地址都送进隧道、或者替 <code>localhost</code> 答 DNS 的代理或 VPN 应用（比如 Clash）会把这个地址也接走：浏览器显示连接错误，App 一直等。两条路：把 <code>localhost</code> 和 <code>127.0.0.1</code> 加进代理应用的直连（绕过）列表再登录一次；或者把那个错误页的地址复制下来，贴进「登录」按钮下方大约十秒后出现的输入框（手机的代理设置会接走这个地址时立刻出现），点「继续」，登录码会不经代理直接交给正在等待的登录流程。Anthropic、xAI 和 OpenRouter 的登录用同一种回跳，也有这个输入框；Kimi 的登录用设备码，不需要它。</p><p><strong>一句老实话。</strong> OpenAI 的条款只允许在它自家的 Codex 里使用 ChatGPT 套餐；其他应用曾被切断过这条路（OpenCode，2026 年 1 月）。哪天它不能用了，API key 仍然可以。</p><h2 id="when-the-provider-cannot-be-reached" tabindex="-1">服务商连不上的时候 <a class="header-anchor" href="#when-the-provider-cannot-be-reached" aria-label="Permalink to &quot;服务商连不上的时候 {#when-the-provider-cannot-be-reached}&quot;">​</a></h2><p>有些网络到不了 <code>chatgpt.com</code>（DNS 不解析、连接超时、TLS 失败、返回的是一张 HTML 拦截页），有些地区 OpenAI 直接拒绝（HTTP 403 <code>unsupported_country_region_territory</code>）。这时手机上的对话不再显示 socket 原文，而是一张卡片：发生了什么（「这个网络连不上 chatgpt.com」或「OpenAI 不向这个地区提供服务」）、能帮上忙的（这台手机上的 VPN；应用自己的代理，设置 → 网络；换一个服务商、用自己的 key）、一个「重试」按钮，原始错误收在「详情」里供提 issue 用。登录失效（401）显示「ChatGPT 登录已失效」和「重新登录」；套餐这几个小时的余量用完（429 且写明 usage limit）显示「ChatGPT 套餐暂时没有余量了」、OpenAI 自己的那句话和多久后恢复；其他 429 是「同时发出的请求太多」。自己的 key 遇到同样的网络问题，卡片一样出现，只是主机名换成那家服务商的。</p><p><strong>设置 → 网络 → 自有服务商的 HTTP 代理</strong>（Android 和 iPhone 都有）：主机、端口、可选的用户名和密码，默认关闭，只存在这台手机上。只有发往你用自己 key 添加的服务商和 ChatGPT 套餐的请求走它；nanoMuse Cloud、你的电脑和局域网从不经过它。页面上有一行「测试」，通过这个代理抓一次 <code>https://chatgpt.com/</code>，告诉你通没通、多少毫秒。同一个设置在每个应用里都放在存 key 的地方：手机在服务商表单里；桌面版在<strong>设置 → nanoMuse Cloud → 网络</strong>，一个地址（<code>http://host:port</code> 或 <code>socks5://host:port</code>），应用在下次启动时写进它的 Host 进程（这一行下面有「立即重启」），于是每把自己的 key、ChatGPT 登录、手的运行时和这个应用对外发出的其他请求都走它，nanoMuse Cloud 永远不走（<a href="./desktop">desktop.md</a>）；网页版在自有 key 表单里有「代理」一栏；运行时是 <code>config.toml</code> 里的 <code>[llm] proxy</code>（<a href="./configuration#llm">configuration.md</a>）。</p><h2 id="local-models" tabindex="-1">本机模型 <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;本机模型 {#local-models}&quot;">​</a></h2><p>Ollama、LM Studio、vLLM 跑在自己电脑上的模型也能用：选对应的预设（网页控制台：「连接」；桌面版：设置 → nanoMuse Cloud；手机：设置 → 服务商），地址默认是本机端口（<code>http://127.0.0.1:11434/v1</code>、<code>:1234</code>、<code>:8000</code>），不需要 key。它们算「对话」；手的模型要能看图，本机跑一个多模态模型（例如 Ollama 的 <code>qwen3-vl</code>）再在「操作屏幕」里选它（网页控制台：「对话模型」下面的「动手模型」一行列出这个端点提供的模型，在那里选它）。画图和视频需要上面表里的一家。</p><h2 id="any-other-openai-compatible-endpoint" tabindex="-1">其他 OpenAI 兼容服务 <a class="header-anchor" href="#any-other-openai-compatible-endpoint" aria-label="Permalink to &quot;其他 OpenAI 兼容服务 {#any-other-openai-compatible-endpoint}&quot;">​</a></h2><p>任何 OpenAI 兼容接口都能填，选「自定义」：</p><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>地址（Base URL）</td><td>服务商给的地址，通常以 <code>/v1</code> 结尾；运行时、网页控制台和桌面版都会拒绝带 <code>user:pass@</code> 的地址（key 有自己的栏位）</td></tr><tr><td>API key</td><td>服务商控制台里创建的 key（本机服务可以留空）</td></tr><tr><td>模型</td><td>保存后从列表里选；接口列不出模型时，表单会请你填模型 id（逗号分开），再按这些保存</td></tr></tbody></table><p>自定义接口能做什么由你来说：nanoMuse 会把它当作对话；手的模型、图片模型、视频模型各自填了 id 才算有。</p><p><strong>几个同时用。</strong> 在桌面版和网页控制台里，自定义接口是一个列表，不是一个槽位（#294）：每个加进来的接口都有自己的 key 和自己的模型，再加一个绝不会替换掉前一个。桌面版的 设置 → 账号 → 任何 OpenAI 兼容接口 下，每个接口一行（名字在上、主机名在下，带「换 key」「改名」「移除」），下面是「添加接口」一行；设置 → 模型 里的选择器把每个接口列成单独一组。网页控制台的 连接 → 对话模型 里，「本地或你自己的端点」下每个接口一块卡片，最后是「添加接口」；双手、图片和短片的选择器也列出这些接口（<a href="./web#where-it-shows">web.md</a>）。列表出现之前设好的自定义接口，下次启动时成为列表的第一项，key 一并带过去。手机上每家服务商还是一个槽位。</p>',46)])])}const y=t(r,[["render",d]]);export{g as __pageData,y as default};
